// Traduce los comandos de Telegram a preguntas para /ask.
//
// No consulta la base por su cuenta: /ask ya resuelve estatus contra
// gps_event y devuelve el texto formateado, con unidad, hora y aviso de dato
// viejo. Duplicar aquí ese formato crearía una segunda versión que se iría
// separando de la de la API.
//
// Los comandos existen porque escribir "/estatus T-142" en el radio mental de
// Tráfico es más rápido y más predecible que redactar una pregunta: no
// dependen de que el router de intenciones reconozca la frase.

const AYUDA = [
  'Consultas de flota:',
  '',
  '/estatus <unidad>      dónde está y desde hace cuánto',
  '/disponibles           unidades en base o en la zona de La Laguna',
  '/sinsenal              unidades sin señal o sin reportar',
  '/atoradas              detenidas en ruta por mucho tiempo',
  '/combustible <unidad>  cargas y descargas de los últimos 7 días',
  '/eventos <unidad>      últimos eventos registrados',
  '/salud                 si está entrando información al sistema',
  '',
  'También puedes preguntar con tus palabras, por ejemplo:',
  '"¿dónde está la T-142?" o "¿qué unidades están libres?"',
].join('\n');

// Comando -> pregunta que el router de /ask reconoce.
const SIN_ARGUMENTO = {
  '/disponibles': '¿qué unidades están disponibles?',
  '/libres': '¿qué unidades están disponibles?',
  '/sinsenal': '¿qué unidades están sin señal?',
  '/atoradas': '¿hay unidades atoradas en ruta?',
  '/salud': '¿está entrando información?',
};

const CON_ARGUMENTO = {
  '/estatus': (u) => `estatus de la unidad ${u}`,
  '/status': (u) => `estatus de la unidad ${u}`,
  '/combustible': (u) => `combustible de la unidad ${u}`,
  '/eventos': (u) => `últimos eventos de la unidad ${u}`,
};

const out = [];

for (const item of $input.all()) {
  const base = item.json;
  const texto = (base.text || '').trim();

  // Mensaje normal: pasa tal cual a /ask.
  if (!texto.startsWith('/')) {
    out.push({ json: { ...base, question: texto, direct_reply: null } });
    continue;
  }

  // En grupos Telegram manda "/estatus@mi_bot"; se limpia el sufijo.
  const partes = texto.split(/\s+/);
  const comando = partes[0].split('@')[0].toLowerCase();
  const argumento = partes.slice(1).join(' ').trim();

  if (comando === '/start' || comando === '/ayuda' || comando === '/help') {
    out.push({ json: { ...base, question: null, direct_reply: AYUDA } });
    continue;
  }

  if (SIN_ARGUMENTO[comando]) {
    out.push({ json: { ...base, question: SIN_ARGUMENTO[comando], direct_reply: null } });
    continue;
  }

  if (CON_ARGUMENTO[comando]) {
    if (!argumento) {
      out.push({
        json: {
          ...base,
          question: null,
          direct_reply: `Falta la unidad. Ejemplo: ${comando} T-142`,
        },
      });
      continue;
    }

    out.push({
      json: { ...base, question: CON_ARGUMENTO[comando](argumento), direct_reply: null },
    });
    continue;
  }

  out.push({
    json: {
      ...base,
      question: null,
      direct_reply: `No conozco el comando ${comando}.\n\n${AYUDA}`,
    },
  });
}

return out;

// Telegram corta los mensajes en 4096 caracteres y una lista de flota
// completa los pasa con facilidad. La API ya devuelve `chunks` partidos por
// salto de línea; aquí solo se convierten en items para que el nodo de envío
// mande uno por mensaje, en orden.

const out = [];

for (const item of $input.all()) {
  const cuerpo = item.json;
  const chat_id = $('Rutear comando').first().json.chat_id;

  const partes =
    Array.isArray(cuerpo.chunks) && cuerpo.chunks.length
      ? cuerpo.chunks
      : [cuerpo.text || 'No encontré respuesta.'];

  for (const parte of partes) {
    out.push({ json: { chat_id, reply: parte } });
  }
}

return out;

// Respuestas que no necesitan la API: ayuda y errores de comando.
return $input.all().map((item) => ({
  json: { chat_id: item.json.chat_id, reply: item.json.direct_reply },
}));
